const validationPassed = $json.validation_passed;

return [
  {
    json: {
      validation_passed: validationPassed
    }
  }
];

const regimes = $('Fetch Today\'s Regime Summary')
    .all()
    .map(item => item.json);

const movers = $('Fetch Top Movers')
    .all()
    .map(item => item.json);


// =====================================================
// FORMAT REGIME SUMMARY
// =====================================================

const regimeSummary = regimes.length > 0

    ? regimes.map((r, index) => {

        const confidence = r.confidence_score
            ? (parseFloat(r.confidence_score) * 100).toFixed(1)
            : 'N/A';

        return (
            `${index + 1}. ${r.regime_label}\n` +
            `   Confidence : ${confidence}%\n` +
            `   Volatility : ${r.volatility_level}\n` +
            `   Assets     : ${r.asset_count}`
        );

    }).join('\n\n')

    : 'No regime data available.';


// =====================================================
// FORMAT TOP MOVERS
// =====================================================

const moversSummary = movers.length > 0

    ? movers.map((m, index) => {

        const rsi = m.rsi
            ? parseFloat(m.rsi).toFixed(1)
            : 'N/A';

        const dailyReturn = m.daily_return
            ? (parseFloat(m.daily_return) * 100).toFixed(2)
            : '0.00';

        const volatility = m.volatility
            ? parseFloat(m.volatility).toFixed(4)
            : 'N/A';

        return (
            `${index + 1}. ${m.ticker_symbol}\n` +
            `   RSI        : ${rsi}\n` +
            `   Return     : ${dailyReturn}%\n` +
            `   Volatility : ${volatility}`
        );

    }).join('\n\n')

    : 'No high-volatility opportunities detected.';


// =====================================================
// DATE FORMATTING
// =====================================================

const today = new Date().toLocaleDateString(

    'en-IN',

    {

        timeZone: 'Asia/Kolkata',

        weekday: 'long',

        year: 'numeric',

        month: 'long',

        day: 'numeric'

    }

);


// =====================================================
// FINAL REPORT
// =====================================================

const report =

`📊 QuantCopilot AI — Daily Market Intelligence Report

📅 ${today}

━━━━━━━━━━━━━━━━━━
🔍 MARKET REGIMES
━━━━━━━━━━━━━━━━━━

${regimeSummary}

━━━━━━━━━━━━━━━━━━
📈 HIGH VOLATILITY OPPORTUNITIES
━━━━━━━━━━━━━━━━━━

${moversSummary}

━━━━━━━━━━━━━━━━━━
✅ SYSTEM STATUS
━━━━━━━━━━━━━━━━━━

• Data Fetching        : Successful
• Indicator Engine     : Successful
• Regime Validation    : Successful
• Report Generation    : Successful

🚀 QuantCopilot AI Pipeline Operational
`;


// =====================================================
// RETURN FINAL JSON
// =====================================================

return [

    {

        json: {

            report,

            generated_at: new Date().toISOString(),

            total_regimes: regimes.length,

            total_movers: movers.length,

            regimes,

            movers

        }

    }

];
